-- =============================================================================
-- Migration 0063: Examentraining — inhoud om de x-as
-- =============================================================================
-- Gegenereerd door scripts/examen-inhoud-x-as.ts — niet met de hand bewerken.
--
-- Eigen onderdeel Examentraining, geen theoriehoofdstuk uit het boek.
-- De inhoud van het lichaam dat ontstaat als een vlakdeel om de x-as wentelt.
-- Vier vragen niveau 2 (grenzen gegeven) en vier niveau 3 (grenzen zelf vinden).
--
-- Eigen oefenvragen, geen boek- of examenopgaven. Elke integraal wordt
-- nagerekend door src/content/primitieven.test.ts
-- (content/hoofdstuk-examen/inhoud-om-de-x-as.json).
--
-- Alleen toevoegen: geen DELETE, DROP, ALTER of UPDATE. Twee keer draaien
-- voegt niets dubbel toe.
--
--   • 1 hoofdstuk, 2 topics, 2 clusters
--   • 8 vragen met elk 4 stappen (32 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('examentraining', $examentrainingsql$Examentraining$examentrainingsql$, 5, 16, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'examentraining' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('examen_inhoud_xas', $examentrainingsql$Inhoud om de x-as$examentrainingsql$, 5, 'toepassingen'),
  ('examen_inhoud_xas_grenzen', $examentrainingsql$Inhoud om de x-as, grenzen zelf$examentrainingsql$, 6, 'toepassingen')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

-- 3. Clusters
INSERT INTO public.topic_clusters_new (topic_id, slug, title, order_index, site)
SELECT t.id, v.slug, v.title, v.order_index, 'integralen'
FROM (VALUES
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Grenzen gegeven$examentrainingsql$, 1),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Grenzen zelf vinden$examentrainingsql$, 1)
) AS v(topic_slug, slug, title, order_index)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
ON CONFLICT (topic_id, slug) DO NOTHING;

-- 4. Vragen
INSERT INTO public.questions_new
  (site, topic_id, cluster_id, latex_body, answer, latex_answer, difficulty, order_index, is_ai_generated, answer_alternatives)
SELECT 'integralen', t.id, cl.id, v.latex_body, v.answer, v.latex_answer, v.difficulty, v.order_index, false, v.alternatives
FROM (VALUES
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x^{2} + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(28/15)pi$examentrainingsql$, $examentrainingsql$\dfrac{28}{15}\pi$examentrainingsql$, 2, 1, ARRAY[$examentrainingsql$(28/15)*pi$examentrainingsql$, $examentrainingsql$28pi/15$examentrainingsql$]::text[]),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(3+4ln(2))pi$examentrainingsql$, $examentrainingsql$(3 + 4\ln(2))\pi$examentrainingsql$, 2, 2, ARRAY[$examentrainingsql$pi*(3+4ln(2))$examentrainingsql$, $examentrainingsql$3pi+4pi*ln(2)$examentrainingsql$]::text[]),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{2x + 3}$, de $x$-as en de lijnen $x = 1$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$14pi$examentrainingsql$, $examentrainingsql$14\pi$examentrainingsql$, 2, 3, ARRAY[$examentrainingsql$14*pi$examentrainingsql$]::text[]),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = e^{x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(1/2)(e^2-1)pi$examentrainingsql$, $examentrainingsql$\dfrac{1}{2}(e^{2} - 1)\pi$examentrainingsql$, 2, 4, ARRAY[$examentrainingsql$(1/2)*pi*(e^2-1)$examentrainingsql$, $examentrainingsql$pi*(e^2-1)/2$examentrainingsql$]::text[]),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(16/15)pi$examentrainingsql$, $examentrainingsql$\dfrac{16}{15}\pi$examentrainingsql$, 3, 1, ARRAY[$examentrainingsql$(16/15)*pi$examentrainingsql$, $examentrainingsql$16pi/15$examentrainingsql$]::text[]),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln(x)$, de $x$-as en de lijn $x = e$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(e-2)pi$examentrainingsql$, $examentrainingsql$(e - 2)\pi$examentrainingsql$, 3, 2, ARRAY[$examentrainingsql$pi*(e-2)$examentrainingsql$, $examentrainingsql$pi*e-2*pi$examentrainingsql$]::text[]),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \sin(x)$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(1/2)pi^2$examentrainingsql$, $examentrainingsql$\dfrac{1}{2}\pi^{2}$examentrainingsql$, 3, 3, ARRAY[$examentrainingsql$pi^2/2$examentrainingsql$, $examentrainingsql$(pi^2)/2$examentrainingsql$]::text[]),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \sqrt{x}$ en $g(x) = \dfrac{1}{2}x$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(8/3)pi$examentrainingsql$, $examentrainingsql$\dfrac{8}{3}\pi$examentrainingsql$, 3, 4, ARRAY[$examentrainingsql$(8/3)*pi$examentrainingsql$, $examentrainingsql$8pi/3$examentrainingsql$]::text[])
) AS v(topic_slug, cluster_slug, latex_body, answer, latex_answer, difficulty, order_index, alternatives)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
WHERE NOT EXISTS (
  SELECT 1 FROM public.questions_new bestaand
  WHERE bestaand.cluster_id = cl.id AND bestaand.latex_body = v.latex_body
);

-- 5. Stappen (step_order 0 t/m 3)
INSERT INTO public.question_steps_new (question_id, step_order, step_description)
SELECT vr.id, v.step_order, v.step_description
FROM (VALUES
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x^{2} + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. Op $[0, 1]$ is $f(x) \ge 1$, dus de grafiek ligt boven de $x$-as. De inhoud is $\pi$ keer de integraal van het kwadraat van $f$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x^{2} + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{1} (x^{2} + 1)^{2}\,\mathrm{d}x = \pi \displaystyle\int_{0}^{1} (x^{4} + 2x^{2} + 1)\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x^{2} + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(x) = \pi\left(\dfrac{1}{5}x^{5} + \dfrac{2}{3}x^{3} + x\right)$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x^{2} + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(1) - F(0) = \pi\left(\dfrac{1}{5} + \dfrac{2}{3} + 1\right) = \pi \cdot \dfrac{28}{15} = \dfrac{28}{15}\pi$. De inhoud is $\dfrac{28}{15}\pi$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. Op $[0, 1]$ zijn teller en noemer positief, dus de grafiek ligt boven de $x$-as. De inhoud is $\pi$ keer de integraal van het kwadraat van $f$. Schrijf de breuk eerst als een getal plus een rest.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$x + 3 = 1\cdot(x + 1) + 2$, dus $f(x) = 1 + \dfrac{2}{x + 1}$. Dan $f(x)^{2} = 1 + \dfrac{4}{x + 1} + \dfrac{4}{(x + 1)^{2}}$. $I(L) = \pi \displaystyle\int_{0}^{1} \left(1 + \dfrac{4}{x + 1} + \dfrac{4}{(x + 1)^{2}}\right)\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$De kern is $x + 1$, met afgeleide $1$. Een primitieve van de integrand is $F(x) = \pi\left(x + 4\ln(x + 1) - \dfrac{4}{x + 1}\right)$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(1) - F(0) = \pi(1 + 4\ln(2) - 2) - \pi(0 - 4) = \pi(4\ln(2) + 3) = (3 + 4\ln(2))\pi$. De inhoud is $(3 + 4\ln(2))\pi$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{2x + 3}$, de $x$-as en de lijnen $x = 1$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. Op $[1, 3]$ is $2x + 3 > 0$, dus de grafiek ligt boven de $x$-as. Het kwadraat van de wortel is $2x + 3$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{2x + 3}$, de $x$-as en de lijnen $x = 1$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{1}^{3} \left(\sqrt{2x + 3}\right)^{2}\,\mathrm{d}x = \pi \displaystyle\int_{1}^{3} (2x + 3)\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{2x + 3}$, de $x$-as en de lijnen $x = 1$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(x) = \pi(x^{2} + 3x)$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{2x + 3}$, de $x$-as en de lijnen $x = 1$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(3) - F(1) = \pi(9 + 9) - \pi(1 + 3) = 18\pi - 4\pi = 14\pi$. De inhoud is $14\pi$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = e^{x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. $e^{x}$ is overal positief. Het kwadraat is $e^{2x}$. De kern van die macht is $2x$, met afgeleide $2$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = e^{x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{1} (e^{x})^{2}\,\mathrm{d}x = \pi \displaystyle\int_{0}^{1} e^{2x}\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = e^{x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(x) = \pi \cdot \dfrac{1}{2}e^{2x}$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = e^{x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(1) - F(0) = \dfrac{1}{2}\pi e^{2} - \dfrac{1}{2}\pi = \dfrac{1}{2}(e^{2} - 1)\pi$. De inhoud is $\dfrac{1}{2}(e^{2} - 1)\pi$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De grafiek snijdt de $x$-as waar $2x - x^{2} = 0$, dus $x(2 - x) = 0$. De snijpunten zijn $x = 0$ en $x = 2$. Daartussen is $f(1) = 1$, dus de grafiek ligt boven de $x$-as. De inhoud is $\pi$ keer de integraal van het kwadraat van $f$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{2} (2x - x^{2})^{2}\,\mathrm{d}x = \pi \displaystyle\int_{0}^{2} (4x^{2} - 4x^{3} + x^{4})\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(x) = \pi\left(\dfrac{4}{3}x^{3} - x^{4} + \dfrac{1}{5}x^{5}\right)$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(2) - F(0) = \pi\left(\dfrac{32}{3} - 16 + \dfrac{32}{5}\right) = \pi\left(\dfrac{160}{15} - \dfrac{240}{15} + \dfrac{96}{15}\right) = \dfrac{16}{15}\pi$. De inhoud is $\dfrac{16}{15}\pi$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln(x)$, de $x$-as en de lijn $x = e$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. $\ln(x) = 0$ bij $x = 1$. Samen met de lijn $x = e$ zijn dat de grenzen. Op $[1, e]$ is $\ln(x) \ge 0$, dus de grafiek ligt boven de $x$-as. De inhoud is $\pi$ keer de integraal van $(\ln x)^{2}$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln(x)$, de $x$-as en de lijn $x = e$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{1}^{e} (\ln(x))^{2}\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln(x)$, de $x$-as en de lijn $x = e$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Met partieel integreren vind je een primitieve van $(\ln x)^{2}$, namelijk $x(\ln x)^{2} - 2x\ln x + 2x$. Een primitieve van de integrand is dus $F(x) = \pi\bigl(x(\ln x)^{2} - 2x\ln x + 2x\bigr)$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln(x)$, de $x$-as en de lijn $x = e$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(e) - F(1) = \pi(e - 2e + 2e) - \pi(2) = \pi e - 2\pi = (e - 2)\pi$. De inhoud is $(e - 2)\pi$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \sin(x)$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. In het eerste kwadrant snijdt $\sin(x)$ de $x$-as in $x = 0$ en $x = \pi$. Daartussen ligt de grafiek boven de $x$-as. De inhoud is $\pi$ keer de integraal van $\sin^{2}(x)$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \sin(x)$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$Gebruik $\sin^{2}(x) = \dfrac{1 - \cos(2x)}{2}$. $I(L) = \pi \displaystyle\int_{0}^{\pi} \dfrac{1 - \cos(2x)}{2}\,\mathrm{d}x$. De kern van de cosinus is $2x$, met afgeleide $2$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \sin(x)$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(x) = \pi\left(\dfrac{1}{2}x - \dfrac{1}{4}\sin(2x)\right)$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \sin(x)$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(\pi) - F(0) = \pi \cdot \dfrac{\pi}{2} - 0 = \dfrac{1}{2}\pi^{2}$. De inhoud is $\dfrac{1}{2}\pi^{2}$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \sqrt{x}$ en $g(x) = \dfrac{1}{2}x$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De grafieken snijden elkaar waar $\sqrt{x} = \dfrac{1}{2}x$. Kwadrateren geeft $x = \dfrac{1}{4}x^{2}$, dus $x(x - 4) = 0$. Beide oplossingen kloppen: $x = 0$ en $x = 4$. Op dat stuk is $f(1) = 1$ groter dan $g(1) = \dfrac{1}{2}$, dus $f$ ligt verder van de $x$-as. De inhoud is $\pi$ keer de integraal van het verschil van de kwadraten.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \sqrt{x}$ en $g(x) = \dfrac{1}{2}x$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{4} \left(x - \left(\dfrac{1}{2}x\right)^{2}\right)\,\mathrm{d}x = \pi \displaystyle\int_{0}^{4} \left(x - \dfrac{1}{4}x^{2}\right)\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \sqrt{x}$ en $g(x) = \dfrac{1}{2}x$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(x) = \pi\left(\dfrac{1}{2}x^{2} - \dfrac{1}{12}x^{3}\right)$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \sqrt{x}$ en $g(x) = \dfrac{1}{2}x$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(4) - F(0) = \pi\left(8 - \dfrac{16}{3}\right) = \dfrac{8}{3}\pi$. De inhoud is $\dfrac{8}{3}\pi$.$examentrainingsql$)
) AS v(topic_slug, cluster_slug, latex_body, step_order, step_description)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
JOIN public.questions_new vr ON vr.latex_body = v.latex_body AND vr.cluster_id = cl.id
ON CONFLICT (question_id, step_order) DO NOTHING;

-- 6. Controle
DO $do$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'examen_inhoud_xas' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'examen_inhoud_xas' AND site = 'integralen'));
  IF n <> 4 THEN RAISE EXCEPTION 'Cluster examen_inhoud_xas hoort 4 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'examen_inhoud_xas_grenzen' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'examen_inhoud_xas_grenzen' AND site = 'integralen'));
  IF n <> 4 THEN RAISE EXCEPTION 'Cluster examen_inhoud_xas_grenzen hoort 4 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.question_steps_new s
  JOIN public.questions_new vr ON vr.id = s.question_id
  JOIN public.topics_new t ON t.id = vr.topic_id
  WHERE t.site = 'integralen' AND t.slug IN ('examen_inhoud_xas', 'examen_inhoud_xas_grenzen');
  IF n <> 32 THEN RAISE EXCEPTION 'Deze topics horen samen 32 stappen te hebben, gevonden %', n; END IF;
END $do$;

COMMIT;
